 "content": "def transform(grid):
    """Connect diamond-shaped 2s with straight lines of 1s across clear gaps."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    seen = set()
    # Each diamond consists of a center-adjacent cross of four 2s.
    for r in range(h):
        for c in range(w):
            if (r, c) in seen or grid[r][c] != 2:
                continue
            # Find connected component of 2s (diagonal adjacency captures the diamond).
            stack = [(r, c)]
            comp = set()
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        q = (y + dy, x + dx)
                        if q not in seen and 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 2:
                            seen.add(q)
                            stack.append(q)
            # The four-cell diamond has its center at the bounding-box midpoint.
            if len(comp) == 4:
                rs = [p[0] for p in comp]
                cs = [p[1] for p in comp]
                centers.append(((min(rs) + max(rs)) // 2, (min(cs) + max(cs)) // 2))
    # Connect pairs sharing a row or column; fill only the empty cells in between.
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i + 1:]:
            if r1 == r2 and c1 != c2:
                lo, hi = sorted((c1, c2))
                if all(grid[r1][c] == 0 for c in range(lo + 1, hi)):
                    for c in range(lo + 1, hi):
                        out[r1][c] = 1
            elif c1 == c2 and r1 != r2:
                lo, hi = sorted((r1, r2))
                if all(grid[r][c1] == 0 for r in range(lo + 1, hi)):
                    for r in range(lo + 1, hi):
                        out[r][c1] = 1
    return out
